/* Recall marketing sites. Generated by Scripts/generate_websites.py; do not edit by hand. */
(function () {
  "use strict";
  var root = document.documentElement;

  // Mobile navigation
  var toggle = document.querySelector("[data-nav-toggle]");
  var nav = document.getElementById("site-nav");
  if (toggle && nav) {
    var setOpen = function (open, returnFocus) {
      nav.classList.toggle("is-open", open);
      toggle.setAttribute("aria-expanded", String(open));
      toggle.setAttribute("aria-label", open ? "Close menu" : "Open menu");
      if (!open && returnFocus) { toggle.focus(); }
    };
    toggle.addEventListener("click", function () {
      setOpen(toggle.getAttribute("aria-expanded") !== "true", false);
    });
    nav.addEventListener("click", function (event) {
      if (event.target.closest("a")) { setOpen(false, false); }
    });
    document.addEventListener("keydown", function (event) {
      if (event.key === "Escape" && toggle.getAttribute("aria-expanded") === "true") { setOpen(false, true); }
    });
    document.addEventListener("click", function (event) {
      if (toggle.getAttribute("aria-expanded") === "true" && !nav.contains(event.target) && !toggle.contains(event.target)) {
        setOpen(false, false);
      }
    });
    window.matchMedia("(min-width: 881px)").addEventListener("change", function () { setOpen(false, false); });
  }

  // Card demo: flip, rate, next card
  Array.prototype.forEach.call(document.querySelectorAll("[data-demo]"), function (demo) {
    var source = document.getElementById(demo.getAttribute("data-demo"));
    var cards = [];
    try { cards = JSON.parse(source ? source.textContent : "[]"); } catch (error) { cards = []; }
    if (!cards.length) { return; }
    var card = demo.querySelector("[data-flip]");
    var faceFront = demo.querySelector("[data-face-front]");
    var faceBack = demo.querySelector("[data-face-back]");
    var deck = demo.querySelector("[data-deck]");
    var front = demo.querySelector("[data-front]");
    var back = demo.querySelector("[data-back]");
    var count = demo.querySelector("[data-count]");
    var progress = demo.querySelector("[data-progress]");
    var live = demo.querySelector("[data-live]");
    var buttons = demo.querySelectorAll("[data-grade]");
    var index = 0;
    var flipped = false;

    var setFlipped = function (value) {
      flipped = value;
      card.classList.toggle("is-flipped", value);
      card.setAttribute("aria-describedby", value ? back.id : front.id);
      faceFront.setAttribute("aria-hidden", String(value));
      faceBack.setAttribute("aria-hidden", String(!value));
      Array.prototype.forEach.call(buttons, function (button) { button.disabled = !value; });
    };
    var show = function (i) {
      index = i;
      deck.textContent = cards[i].deck;
      front.textContent = cards[i].front;
      back.textContent = cards[i].back;
      count.textContent = (i + 1) + " of " + cards.length;
      if (progress) { progress.style.width = Math.round((i + 1) / cards.length * 100) + "%"; }
      if (cards[i].tint) { demo.setAttribute("data-tint", cards[i].tint); }
      setFlipped(false);
    };
    card.addEventListener("click", function () {
      setFlipped(!flipped);
      live.textContent = flipped ? "Answer: " + cards[index].back : "Question: " + cards[index].front;
    });
    Array.prototype.forEach.call(buttons, function (button) {
      button.addEventListener("click", function () {
        if (!flipped) { return; }
        var label = button.querySelector("span").textContent;
        show((index + 1) % cards.length);
        live.textContent = "Rated " + label + ". Next card: " + cards[index].front;
        card.focus();
      });
    });
    demo.addEventListener("keydown", function (event) {
      var n = parseInt(event.key, 10);
      if (flipped && n >= 1 && n <= buttons.length) {
        event.preventDefault();
        buttons[n - 1].click();
      }
    });
  });

  // Header hairline once the page has scrolled
  var header = document.querySelector(".site-header");
  if (header) {
    var onScroll = function () { header.classList.toggle("is-scrolled", window.scrollY > 4); };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
  }

  // Screenshot gallery: previous and next buttons, disabled at either end
  Array.prototype.forEach.call(document.querySelectorAll("[data-rail]"), function (rail) {
    var nav = rail.parentNode.querySelector("[data-rail-nav]");
    var prev = nav && nav.querySelector("[data-rail-prev]");
    var next = nav && nav.querySelector("[data-rail-next]");
    if (!prev || !next) { return; }
    var step = function (direction) {
      var item = rail.querySelector("li");
      var gap = parseFloat(getComputedStyle(item.parentNode).columnGap) || 0;
      rail.scrollBy({ left: direction * (item.getBoundingClientRect().width + gap),
                      behavior: root.classList.contains("motion") ? "smooth" : "auto" });
    };
    var update = function () {
      var atStart = rail.scrollLeft <= 2;
      var atEnd = rail.scrollLeft + rail.clientWidth >= rail.scrollWidth - 2;
      prev.disabled = atStart && prev.disabled;   // enable first: a disabled button cannot take focus
      next.disabled = atEnd && next.disabled;
      if (atEnd && !atStart && document.activeElement === next) { prev.focus(); }
      if (atStart && !atEnd && document.activeElement === prev) { next.focus(); }
      prev.disabled = atStart;
      next.disabled = atEnd;
      nav.hidden = prev.disabled && next.disabled;
    };
    prev.addEventListener("click", function () { step(-1); });
    next.addEventListener("click", function () { step(1); });
    rail.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", update);
    update();
  });

  // Film: our play button starts it; the native controls take over from there
  Array.prototype.forEach.call(document.querySelectorAll("[data-film]"), function (frame) {
    var video = frame.querySelector("video");
    var play = frame.querySelector("[data-film-play]");
    var vertical = video.querySelector("source[media]");
    var posterVertical = video.getAttribute("data-poster-vertical");
    if (vertical && window.matchMedia(vertical.getAttribute("media")).matches) {
      // the vertical cut burns its captions in, and the caption track is timed to the 16:9 cut
      if (posterVertical) { video.poster = posterVertical; }
      Array.prototype.forEach.call(video.querySelectorAll("track"), function (track) { video.removeChild(track); });
    }
    play.addEventListener("click", function () {
      frame.classList.add("is-playing");
      var started = video.play();
      if (started && started.catch) { started.catch(function () { frame.classList.remove("is-playing"); }); }
      video.focus();
    });
    video.addEventListener("play", function () { frame.classList.add("is-playing"); });
    video.addEventListener("ended", function () { frame.classList.remove("is-playing"); });
  });

  // Reveal on scroll (only when motion is allowed; the CSS shows everything otherwise)
  var revealables = document.querySelectorAll(".reveal");
  if (root.classList.contains("motion") && "IntersectionObserver" in window) {
    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-visible");
          observer.unobserve(entry.target);
        }
      });
    }, { rootMargin: "0px 0px -8% 0px", threshold: 0.06 });
    Array.prototype.forEach.call(revealables, function (el) { observer.observe(el); });
  } else {
    Array.prototype.forEach.call(revealables, function (el) { el.classList.add("is-visible"); });
  }
})();
